#!/usr/bin/env node
/**
 * Tests for hooks/scope-guard.js, alone and through hooks/nudges.js. Zero dependencies — `node:test`
 * on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * Each case builds a throwaway repository (a `.git` folder is all the hook looks for) with a plan file
 * under docs/plans, and drives the hook the way the harness does: one PostToolUse payload per edit.
 * Most cases are the silences, because a nudge that speaks without a perimeter gets switched off.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const GUARD = join(ROOT, 'hooks', 'scope-guard.js');
const NUDGES = join(ROOT, 'hooks', 'nudges.js');
const created = [];
process.on('exit', () => {
  for (const dir of created) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp */ } }
});

const PERIMETER = [
  '# Plan', '', '```perimeter', 'status: active', '- src/Orders/OrdersQuery.cs', '- src/Orders/Dto/', '- tests/**/Orders*.cs', '```', '',
].join('\n');

/** A repository with the given plan files ({ name: text }); returns its root. */
function repo(plans = { '2026-10-22-orders.md': PERIMETER }) {
  const root = mkdtempSync(join(tmpdir(), 'scopeguard-'));
  created.push(root);
  mkdirSync(join(root, '.git'));
  mkdirSync(join(root, 'src', 'Orders'), { recursive: true });
  mkdirSync(join(root, 'docs', 'plans'), { recursive: true });
  for (const [name, text] of Object.entries(plans)) writeFileSync(join(root, 'docs', 'plans', name), text);
  return root;
}

/** The `additionalContext` the hook printed for an edit of `file`, '' when silent. */
function edit(root, file, extra = {}, hook = GUARD) {
  const r = spawnSync(process.execPath, [hook], {
    input: JSON.stringify({
      session_id: 's', hook_event_name: 'PostToolUse', tool_name: 'Edit', cwd: root,
      tool_input: { file_path: join(root, file) }, ...extra,
    }),
    encoding: 'utf8',
    env: { ...process.env, CLAUDE_CONFIG_DIR: root },
  });
  assert.equal(r.status, 0, r.stderr);
  return r.stdout ? JSON.parse(r.stdout).hookSpecificOutput.additionalContext : '';
}

test('a file outside the active perimeter → one line naming the file and the plan', () => {
  const out = edit(repo(), 'src/Orders/OrdersController.cs');
  assert.match(out, /^Fuori perimetro: `src\/Orders\/OrdersController\.cs`/);
  assert.match(out, /docs\/plans\/2026-10-22-orders\.md/);
  assert.match(out, /chiedi all'utente/);
});

test('files inside: a listed file, a directory, a glob → silent', () => {
  const root = repo();
  assert.equal(edit(root, 'src/Orders/OrdersQuery.cs'), '');
  assert.equal(edit(root, 'src/Orders/Dto/Deep/Line.cs'), '');
  assert.equal(edit(root, 'tests/unit/OrdersQueryTests.cs'), '');
});

test('no plan, no block, or a closed perimeter → no-op', () => {
  assert.equal(edit(repo({}), 'src/Anything.cs'), '');
  assert.equal(edit(repo({ 'a.md': '# a plan with no perimeter block\n' }), 'src/Anything.cs'), '');
  assert.equal(edit(repo({ 'a.md': PERIMETER.replace('status: active', 'status: closed') }), 'src/Anything.cs'), '');
});

test('the plan files themselves, and a path outside any repository → silent', () => {
  const root = repo();
  assert.equal(edit(root, 'docs/plans/2026-10-22-orders.md'), '');
  const loose = mkdtempSync(join(tmpdir(), 'scopeguard-loose-'));
  created.push(loose);
  assert.equal(edit(root, join('..', loose.split(/[\\/]/).pop(), 'x.cs')), '');
});

test('two active perimeters add up; a closed one does not', () => {
  const root = repo({
    'a.md': PERIMETER,
    'b.md': PERIMETER.replace('src/Orders/OrdersQuery.cs', 'src/Billing/Invoice.cs'),
    'c.md': PERIMETER.replace('status: active', 'status: closed').replace('src/Orders/OrdersQuery.cs', 'src/Old/Closed.cs'),
  });
  assert.equal(edit(root, 'src/Billing/Invoice.cs'), '');
  assert.match(edit(root, 'src/Old/Closed.cs'), /^Fuori perimetro/);
});

test('MultiEdit and Write count; Read and other events do not', () => {
  const root = repo();
  assert.match(edit(root, 'src/Other.cs', { tool_name: 'MultiEdit' }), /^Fuori perimetro/);
  assert.match(edit(root, 'src/Other.cs', { tool_name: 'Write' }), /^Fuori perimetro/);
  assert.equal(edit(root, 'src/Other.cs', { tool_name: 'Read' }), '');
  assert.equal(edit(root, 'src/Other.cs', { hook_event_name: 'UserPromptSubmit' }), '');
});

test('inside a subagent the line says Open questions, since a subagent never asks', () => {
  assert.match(edit(repo(), 'src/Other.cs', { agent_id: 'a1' }), /Open questions/);
});

test('through nudges.js the same line comes out as additionalContext', () => {
  assert.match(edit(repo(), 'src/Other.cs', {}, NUDGES), /^Fuori perimetro/);
});

test('garbage on stdin → silence, exit 0', () => {
  const r = spawnSync(process.execPath, [GUARD], { input: 'not json', encoding: 'utf8' });
  assert.equal(r.status, 0);
  assert.equal(r.stdout, '');
});
